{"implementation": "def solve(case):
    payload = case['payload']
    tokens = list(payload['tokens'])  # copy to avoid mutation
    calls = payload['calls']
    # Validate calls
    if not isinstance(tokens, list) or not isinstance(calls, list):
        raise ValueError('Invalid payload structure')
    n = len(tokens)
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError('Each call must be a dict')
        required = ['call_id', 'start', 'end', 'score', 'replacement_tokens']
        for key in required:
            if key not in call:
                raise ValueError(f'Missing key {key} in call')
        start, end = call['start'], call['end']
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError('start and end must be integers')
        if not (0 <= start < end <= n):
            raise ValueError('Invalid span indices')
        if not isinstance(call['replacement_tokens'], list):
            raise ValueError('replacement_tokens must be a list')
        if not isinstance(call['score'], (int, float)):
            raise ValueError('score must be numeric')
    # Sort by descending score, ascending start, then call_id
    sorted_calls = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    # Greedy selection
    selected = []
    intervals = []  # list of (start, end) for selected
    for call in sorted_calls:
        s, e = call['start'], call['end']
        overlap = False
        for (ss, ee) in intervals:
            if s < ee and e > ss:
                overlap = True
                break
        if not overlap:
            selected.append(call)
            intervals.append((s, e))
    # Order selected by start
    selected.sort(key=lambda c: c['start'])
    # Apply replacements from right to left (by start descending)
    result_tokens = list(tokens)
    for call in sorted(selected, key=lambda c: c['start'], reverse=True):
        s, e = call['start'], call['end']
        rep = call['replacement_tokens']
        result_tokens = result_tokens[:s] + rep + result_tokens[e:]
    return {
        'selected_call_ids': [c['call_id'] for c in selected],
        'result_tokens': result_tokens
    }
